on conflict (id) do update set cambios = excluded.cambios, actual = excluded.actual, seguridad = excluded.seguridad, razon = excluded.razon
  where public.propuestas_unidad.estado = 'PENDIENTE' and public.propuestas_unidad.cambios is distinct from excluded.cambios;

